create function public.fail_profile_audit() returns trigger language plpgsql as $$ begin if new.action='PERSON_PROFILE_DELETED' then raise exception 'Forced audit failure' using errcode='23514'; end if; return new; end; $$;
create trigger fail_profile_audit before insert on public.audit_events for each row execute function public.fail_profile_audit();
set local role authenticated;
select set_config('request.jwt.claim.sub','72000000-0000-0000-0000-000000000001',true);
